return ['domain'=>'mlab-seo','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr','project-id-version'=>'MomentumLab SEO 1.9.1','pot-creation-date'=>'2026-11-09T23:31:10+00:00','po-revision-date'=>'2026-11-09T23:31:10+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['MomentumLab SEO'=>'MomentumLab SEO','https://momentumlab.ch/'=>'https://momentumlab.ch/','Search engine and AI optimisation: titles, meta descriptions, Google preview with SEO check, social previews, schema.org, sitemap, robots.txt and llms.txt for AI assistants.'=>'Optimisation pour les moteurs de recherche et l’IA : titres, méta-descriptions, aperçu Google avec contrôle SEO, aperçus pour les réseaux sociaux, schema.org, sitemap, robots.txt et llms.txt pour les assistants IA.','MomentumLab'=>'MomentumLab','Overview'=>'Aperçu','Pages'=>'Pages','Title, description and previews of all pages in one place. Click a row to edit it.'=>'Titre, description et aperçus de toutes les pages au même endroit. Cliquez sur une ligne pour la modifier.','All pages'=>'Toutes les pages','Content check'=>'Contrôle des contenus','Sitemap'=>'Sitemap','The list of all pages for Google and Bing. Hidden pages are left out automatically.'=>'La liste de toutes les pages pour Google et Bing. Les pages masquées sont exclues automatiquement.','Redirects'=>'Redirections','Old addresses lead to the new page, so links and rankings are kept.'=>'Les anciennes adresses mènent à la nouvelle page, ainsi les liens et le classement sont conservés.','Search appearance'=>'Apparence dans les résultats de recherche','How Google, social media and AI assistants show the website.'=>'Comment Google, les réseaux sociaux et les assistants IA présentent le site web.','Home page'=>'Page d’accueil','Templates'=>'Modèles','Organisation'=>'Organisation','AI & crawlers'=>'IA et robots d’exploration','Who may read the website, and what AI assistants learn about it.'=>'Qui peut lire le site web et ce que les assistants IA en apprennent.','Crawlers'=>